    $role = $msg['role'] === 'user' ? 'user' : 'assistant';
    $text = '';
    foreach ($msg['parts'] as $part) {
        $text .= $part['text'] ?? '';
    }
    $messages[] = [
        'role'    => $role,
        'content' => $text,
    ];
}

